  "description": "Get one order's status by ID.",
  "parameters": {
    "type": "object",
    "properties": {
      "order_id": {
        "type": "string",
        "description": "Order ID, e.g. A-1042"
      }
    },
    "required": ["order_id"]
  }
}

const res = await client.messages.create({
  model: "claude-sonnet-5-5",
  max_tokens: 1024,
  tools,
  messages,
});
messages.push({
  role: "assistant", content: res.content,
});
const results = [];
for (const block of res.content) {
  if (block.type === "tool_use") {
    const out = await run(block.name, block.input);
    results.push({
      type: "tool_result",
      tool_use_id: res.id,
      content: out,
    });
  }
}
messages.push({ role: "user", content: results });

